"use client";

import { useState } from "react";
import { ChevronLeft, ChevronRight, Plus, FileText } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, isSameDay, addDays } from "date-fns";
import TaskFormModal from "@/components/tasks/TaskFormModal"; // Modal bileşenini buraya import ediyoruz

export default function CalendarClient({ initialTasks }: { initialTasks: any[] }) {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date());

  // Task'ları tarih bazlı gruplama (Hızlı erişim için)
  const taskMap = initialTasks.reduce((acc: any, task) => {
    try {
      const data = JSON.parse(task.description || "{}");
      const dateKey = data.datum; // "2024-05-20" formatında olmalı
      if (!acc[dateKey]) acc[dateKey] = [];
      acc[dateKey].push({ ...task, data });
    } catch (e) { console.error("Data parse hatası"); }
    return acc;
  }, {});

  // Bir güne tıklandığında çalışacak fonksiyon
  const handleDayClick = (day: Date) => {
    setSelectedDate(day);
    setIsModalOpen(true);
  };

  const renderHeader = () => (
    <div className="flex justify-between items-center mb-10 border-b border-teal-500/10 pb-6">
      <div>
        <h1 className="text-4xl font-black text-white italic tracking-tighter uppercase leading-none">Temporal Grid</h1>
        <p className="text-teal-500/50 text-[10px] font-bold tracking-[0.4em] mt-2 uppercase">{format(currentMonth, "MMMM yyyy")}</p>
      </div>
      <div className="flex gap-4">
        <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="p-3 border border-teal-500/20 hover:bg-teal-500/10 text-teal-500 transition-all">
          <ChevronLeft size={20} />
        </button>
        <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="p-3 border border-teal-500/20 hover:bg-teal-500/10 text-teal-500 transition-all">
          <ChevronRight size={20} />
        </button>
      </div>
    </div>
  );

  const renderDays = () => {
    const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
    return (
      <div className="grid grid-cols-7 mb-2">
        {days.map((day) => (
          <div key={day} className="text-[10px] font-black text-fuchsia-500 uppercase tracking-widest text-center py-2">{day}</div>
        ))}
      </div>
    );
  };

  const renderCells = () => {
    const monthStart = startOfMonth(currentMonth);
    const monthEnd = endOfMonth(monthStart);
    const startDate = startOfWeek(monthStart, { weekStartsOn: 1 });
    const endDate = endOfWeek(monthEnd, { weekStartsOn: 1 });

    const rows = [];
    let days = [];
    let day = startDate;

    while (day <= endDate) {
      for (let i = 0; i < 7; i++) {
        const formattedDate = format(day, "yyyy-MM-dd");
        const dayTasks = taskMap[formattedDate] || [];
        const isSelected = isSameDay(day, new Date());
        const isCurrentMonth = isSameMonth(day, monthStart);

        days.push(
          <div
            key={day.toString()}
            onClick={() => handleDayClick(day)} // Hücreye tıklama özelliği
            className={`min-h-[130px] border border-teal-500/5 p-3 transition-all cursor-pointer group relative ${
              !isCurrentMonth ? "opacity-20 pointer-events-none" : "opacity-100"
            } ${isSelected ? "bg-teal-500/5 border-teal-500/30" : "hover:bg-white/[0.03] hover:border-teal-500/20"}`}
          >
            <div className="flex justify-between items-start mb-2">
              <span className={`text-[11px] font-mono ${isSelected ? "text-fuchsia-500 font-black underline" : "text-teal-500/40"}`}>
                {format(day, "d")}
              </span>
              <Plus size={12} className="text-teal-500/0 group-hover:text-teal-500/60 transition-all" />
            </div>
            
            <div className="space-y-1.5 overflow-hidden">
              {dayTasks.map((t: any) => (
                <div key={t.id} className="text-[9px] bg-fuchsia-600/10 border-l-2 border-fuchsia-500 p-1.5 truncate text-teal-100 flex items-center gap-1.5 shadow-[2px_2px_5px_rgba(0,0,0,0.3)]">
                  <FileText size={10} className="text-fuchsia-400" />
                  <span className="font-bold tracking-tighter uppercase">{t.data.documentType}</span>
                </div>
              ))}
            </div>
          </div>
        );
        day = addDays(day, 1);
      }
      rows.push(<div className="grid grid-cols-7" key={day.toString()}>{days}</div>);
      days = [];
    }
    return <div className="bg-[#0a0e17]/80 border border-white/5 rounded-b-xl">{rows}</div>;
  };

  return (
    <div className="max-w-7xl mx-auto pb-20">
      {renderHeader()}
      
      {/* TAKVİM IZGARASI */}
      <div className="bg-[#0E153A]/20 backdrop-blur-3xl p-1 border border-teal-500/10 rounded-2xl shadow-[0_0_50px_rgba(0,0,0,0.5)]">
        {renderDays()}
        {renderCells()}
      </div>

      {/* MODAL ENTEGRASYONU */}
      {/* TaskFormModal'ın initialDate prop'unu desteklediğinden emin ol */}
      <TaskFormModal 
        open={isModalOpen} 
        setOpen={setIsModalOpen} 
        initialDate={format(selectedDate, "yyyy-MM-dd")} 
      />

      {/* SÜSLEME (Alt Bilgi) */}
      <div className="mt-6 flex gap-6 items-center justify-center">
         <div className="flex items-center gap-2 text-[9px] font-bold text-teal-500/40 uppercase tracking-widest">
            <div className="w-2 h-2 bg-fuchsia-500 rounded-full" /> Logs Present
         </div>
         <div className="flex items-center gap-2 text-[9px] font-bold text-teal-500/40 uppercase tracking-widest">
            <div className="w-2 h-2 border border-teal-500/40 rounded-full" /> System Empty
         </div>
      </div>
    </div>
  );
}