{/* CalendarClient.tsx içindeki renderCells fonksiyonu */}
{dayTasks.map((t: any) => {
  const isAgenda = t.data.documentType === 'agenda' || t.data.documentType === 'assignment';
  return (
    <div 
      key={t.id} 
      className={`text-[9px] p-1.5 truncate flex items-center gap-1.5 shadow-md border-l-2 ${
        isAgenda 
          ? "bg-blue-600/20 border-blue-400 text-blue-100" // Ajanda için mavi tema
          : "bg-fuchsia-600/10 border-fuchsia-500 text-teal-100" // Scrum için pembe tema
      }`}
    >
      <span>{isAgenda ? "📌" : "📄"}</span>
      <span className="font-bold tracking-tighter uppercase">{t.title}</span>
    </div>
  );
})}